210	    /**
211	     * Applies the household-membership rules for a newly normalized owner being created. The
212	     * household id is a deterministic function of the owner's last name and postcode, so owners
213	     * with the same last name and postcode share it automatically; it is assigned to the new owner
214	     * here. Because the household is keyed on (last name, postcode), any existing owner with the
215	     * same last name and postcode is a member of the same household: a second such owner is rejected
216	     * as a household duplicate (409) unless the request declares it shares the household via
217	     * {@code sharesHousehold}, in which case it is created as a declared household member. The
218	     * owner's {@code householdSize} (the number of owners sharing the household after this create)
219	     * is recorded either way. The assigned household id is part of the owner's identity key, so it
220	     * is resolved here before {@link #rejectWhenIdentityInUse}.
221	     *
222	     * @param owner           the newly mapped and normalized owner being created
223	     * @param sharesHousehold whether the request declared that the owner shares an existing household
224	     * @return {@code true} if the owner joined an existing household as a declared member
225	     */
226	    private boolean applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
227	        // Assign the deterministic household id (a pure function of last name and postcode) so every
228	        // owner with the same last name and postcode shares it automatically.
229	        owner.setHouseholdId(householdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
230	        // Identify any existing owners in the same household (same computed household id).
231	        List<Owner> householdMembers = sameHouseholdOwners(owner);
232	        // A second owner in an existing household is a household duplicate: reject it with 409 unless
233	        // the request declares it shares the household, in which case create it as a declared member.
234	        boolean declaredHouseholdMember = false;
235	        if (!householdMembers.isEmpty()) {
236	            if (!sharesHousehold) {
237	                throw new HouseholdDuplicateException(
238	                    "An owner in the household " + owner.getHouseholdId() + " already exists");
239	            }
240	            declaredHouseholdMember = true;
241	        }
242	        // Record the size of this owner's household after this create, fixed at creation time.
243	        owner.setHouseholdSize(householdMembers.size() + 1);
244	        return declaredHouseholdMember;
245	    }
