273	    /**
274	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
275	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) joins the normalized
276	     * telephone, the email (or empty) and the household id (or empty), so this single rule replaces
277	     * the former separate telephone, email and household duplicate checks: two owners collide only
278	     * when their whole keys are equal, and members of one household with different telephones have
279	     * different keys and are both allowed.
280	     *
281	     * @param owner the owner being created, already normalized and with its household resolved
282	     */
283	    private void rejectWhenIdentityInUse(Owner owner) {
284	        String identityKey = owner.getIdentityKey();
285	        boolean inUse = existingOwners()
286	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
287	        if (inUse) {
288	            throw new DuplicateIdentityException(
289	                "An owner with identity key " + identityKey + " already exists");
290	        }
291	    }
