364	    /**
365	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
366	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
367	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
368	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
369	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
370	     * server's current date. Canonicalising the address here, before the household checks read it,
371	     * ensures duplicate detection and the shared household id both compare the normalized form.
372	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
373	     * duplicate, household and customer-code rules.
374	     *
375	     * @param owner the newly mapped owner to canonicalize
376	     */
377	    private void normalizeOwnerFields(Owner owner) {
378	        // Canonicalize the owner's address fields on create so the address is stored and returned in
379	        // canonical form and every later comparison (household duplicate detection and the shared
380	        // household id) uses it. A value that is blank after normalization is rejected with 400.
381	        normalizeAddressFields(owner);
382	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
383	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
384	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
385	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
386	        // Store the (already syntactically validated) email lower-cased so it is persisted and
387	        // returned in canonical form. A missing email is left untouched.
388	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
389	        // Reject an email whose domain is on the disposable-domain blocklist with 400, after
390	        // canonicalization so the comparison sees the lower-cased value.
391	        rejectDisposableEmailDomain(owner.getEmail());
392	        // Validate the optional postcode against the fixed range for the city's region. A postcode
393	        // is checked only when present (it is optional); one out of range for the city's region is
394	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
395	        // value is left unchanged.
396	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
397	        // Reject a supplied registration date that is later than the server's current date with
398	        // 400, before any defaulting or business-day adjustment, so a future date is never
399	        // persisted regardless of how the roll-forward would move it.
400	        rejectFutureRegistrationDate(owner.getRegistrationDate());
401	        // Default the registration date to the server's current date when the client did not
402	        // supply one, then roll the effective date forward to a business day so a Saturday or
403	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
404	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
405	        // date-derived field (such as the membership number's year segment) and the per-day
406	        // create-limit are computed from.
407	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
408	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
409	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
410	    }
