412	    /**
413	     * Canonicalizes a newly mapped owner's address on create, in place, so it is persisted and
414	     * returned in canonical form. The address is normalized (trimmed, whitespace collapsed,
415	     * upper-cased and common street-type abbreviations expanded) via {@link AddressNormalizer}, and a
416	     * value blank after normalization is rejected with 400. Canonicalising the address here, before
417	     * the household checks read it, ensures duplicate detection and the shared household id both
418	     * compare the normalized form. Isolating the address concern in its own helper keeps
419	     * {@link #normalizeOwnerFields} focused on sequencing the per-field canonicalizations.
420	     *
421	     * @param owner the newly mapped owner whose address is canonicalized
422	     */
423	    private void normalizeAddressFields(Owner owner) {
424	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
425	    }
