427	    /**
428	     * Rejects a supplied email whose domain is on the disposable-domain blocklist
429	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}) with a 400 Bad Request. The email is already canonicalized
430	     * (lower-cased) here, so the domain — the part after the final {@code '@'} — is compared directly
431	     * against the lower-cased blocklist. A {@code null} email (email is optional) or one without a
432	     * domain part is left untouched.
433	     *
434	     * @param email the owner's canonicalized email, or {@code null} when absent
435	     */
436	    private void rejectDisposableEmailDomain(String email) {
437	        if (email == null) {
438	            return;
439	        }
440	        int at = email.lastIndexOf('@');
441	        if (at < 0) {
442	            return;
443	        }
444	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
445	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
446	            throw new DisposableEmailException(
447	                "The supplied email domain " + domain + " is on the disposable-domain blocklist");
448	        }
449	    }
450	
451	    /**
452	     * Rejects a supplied registration date that is later than the server's current date with a
453	     * 400 Bad Request. A missing registration date (defaulted to the server date later) is
454	     * accepted, and a date on or before today is left for the normal defaulting and business-day
455	     * adjustment.
456	     *
457	     * @param registrationDate the client-supplied registration date, or {@code null} when absent
458	     */
459	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
460	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
461	            throw new InvalidRegistrationDateException(
462	                "The supplied registration date " + registrationDate + " is later than the current date");
463	        }
464	    }
465	
466	    /**
467	     * Rolls a registration date forward to a business day: a Saturday or Sunday advances to the
468	     * following Monday, while a weekday is returned unchanged. Applied to the effective
469	     * registration date (whether supplied in the request or defaulted to the server date) so the
470	     * persisted registration date, every value derived from it and the per-day create-limit all
471	     * use the adjusted business day.
472	     *
473	     * @param date the effective registration date
474	     * @return the same date if it is a weekday, otherwise the following Monday
475	     */
476	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
477	        java.time.LocalDate adjusted = date;
478	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
479	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
480	            adjusted = adjusted.plusDays(1);
481	        }
482	        return adjusted;
483	    }
