485	    /**
486	     * Builds the customer code '<REGION>-<HASH8>' for a newly created owner, where REGION is the
487	     * region derived from the owner's postcode (falling back to the city, via
488	     * {@link LocalityResolver}) and HASH8 is the first 8 upper-case hex characters of the SHA-256
489	     * digest over the owner's normalized telephone concatenated with the last name (e.g.
490	     * 'NSW-A1B2C3D4'). When that base code already belongs to an existing owner, '-<n>' is appended
491	     * with the smallest n of 2 or more that makes it unique, so distinct owners always receive
492	     * distinct customer codes.
493	     *
494	     * @param owner the owner being created, already normalized
495	     * @return the formatted, de-duplicated customer code
496	     */
497	    private String customerCode(Owner owner) {
498	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
499	        String hash8 = Sha256Hex.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
500	        String base = region + "-" + hash8;
501	        Set<String> taken = existingOwners()
502	            .map(Owner::getCustomerCode)
503	            .filter(code -> code != null)
504	            .collect(Collectors.toSet());
505	        if (!taken.contains(base)) {
506	            return base;
507	        }
508	        int n = 2;
509	        while (taken.contains(base + "-" + n)) {
510	            n++;
511	        }
512	        return base + "-" + n;
513	    }
