515	    /**
516	     * Streams the existing owners that the create-time rules match a new owner against. Every
517	     * duplicate, quota and derived-field rule scans this same set of owners and differs only in the
518	     * predicate it applies, so fetching them is centralized here to keep each rule focused on its
519	     * own matching criterion rather than on how the existing owners are retrieved.
520	     *
521	     * @return a stream over all existing owners
522	     */
523	    private Stream<Owner> existingOwners() {
524	        return this.clinicService.findAllOwners().stream();
525	    }
