527	    /**
528	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
529	     * fix the per-city sequence of an owner's customer code at creation time.
530	     *
531	     * @param city the city of the owner being created
532	     * @return the number of existing owners in a matching city
533	     */
534	    private int countOwnersInCity(String city) {
535	        return (int) existingOwners()
536	            .filter(existing -> existing.getCity() != null
537	                && existing.getCity().equalsIgnoreCase(city))
538	            .count();
539	    }
540	
541	    /**
542	     * Counts the existing owners whose registration date is the given adjusted business day. Used
543	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
544	     * owners already carry that business day as their registration date.
545	     *
546	     * @param date the adjusted business-day registration date to match
547	     * @return the number of existing owners registered on that date
548	     */
549	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
550	        return (int) existingOwners()
551	            .filter(existing -> date.equals(existing.getRegistrationDate()))
552	            .count();
553	    }
554	
555	    /**
556	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
557	     * the last two digits of the registration date's year (e.g. 'NSW-A1B2C3D4-M26').
558	     *
559	     * @param customerCode     the owner's customer code
560	     * @param registrationDate the owner's registration date
561	     * @return the formatted membership number
562	     */
563	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
564	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
565	    }
566	
567	    /**
568	     * Returns the existing owners in the given owner's household, i.e. those sharing its
569	     * deterministic household id (the same last name and postcode). The id is computed via
570	     * {@link HouseholdNormalizer} so that last names differing only in letter case or in incidental
571	     * whitespace are treated as the same household. Centralising how "the same household" is matched
572	     * here keeps that definition in one place for every caller.
573	     *
574	     * @param owner the owner being created, with its household id already assigned
575	     * @return the existing owners in the owner's household (possibly empty)
576	     */
577	    private List<Owner> sameHouseholdOwners(Owner owner) {
578	        String householdId = owner.getHouseholdId();
579	        return existingOwners()
580	            .filter(existing -> householdId.equals(
581	                householdNormalizer.householdId(existing.getLastName(), existing.getPostcode())))
582	            .toList();
583	    }
584	
585	    /**
586	     * Counts the existing owners who share the given first and last name, compared
587	     * case-insensitively. Used to fix an owner's namesake count at creation time.
588	     *
589	     * @param firstName the first name of the owner being created
590	     * @param lastName  the last name of the owner being created
591	     * @return the number of existing owners with a matching first and last name
592	     */
593	    private int countNamesakes(String firstName, String lastName) {
594	        return (int) existingOwners()
595	            .filter(existing -> existing.getFirstName() != null
596	                && existing.getFirstName().equalsIgnoreCase(firstName)
597	                && existing.getLastName() != null
598	                && existing.getLastName().equalsIgnoreCase(lastName))
599	            .count();
600	    }
